#include <openssl/md5.h>
#include <openssl/sha.h>
#include <cstring>
#include <sstream>
#include <random>

std::string hash_password_md5(const std::string& pass) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)pass.c_str(), pass.length(), digest);
    std::stringstream ss;
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++)
        ss << std::hex << (int)digest[i];
    return ss.str();
}

int generate_random_iv() {
    return rand() % 65536;  // 16-bit IV
}
